[140] = {"桑德爾船長的寶藏", {"找到桑德爾船長的箱子並打開它，取得你的獎勵。"}},
[141] = {"迪菲亞兄弟會", {"將肖爾的報告交給西部荒野的格萊恩·斯托曼。"}},
[142] = {"迪菲亞兄弟會", {"追蹤西部荒野的迪菲亞信差，並將他身上攜帶的信件交給斯托曼。"}},
[143] = {"送往西部荒野的信", {"所羅門鎮長要求你給西部荒野的格里安·斯托曼送一封信。"}},
[144] = {"送信到西部荒野", {"將格萊恩·斯托曼的回信帶給所羅門鎮長。"}},
[145] = {"送信到夜色鎮", {"所羅門鎮長要求你送一封信給夜色鎮的埃伯洛克公爵。"}},
[146] = {"送信到夜色鎮", {"將埃伯洛克公爵的回信送回去給所羅門鎮長。"}},
[147] = {"獵殺收貨人", {"找到「收貨人」並將他殺掉，然後帶著收貨人的戒指回來見治安官杜漢。"}},
[148] = {"來自夜色鎮的補給", {"和伊娃夫人談話。"}},
[149] = {"幽靈的髮絲", {"把幽靈髮梳帶給盲眼瑪麗。"}},
[150] = {"魚人偷獵者", {"帶8片魚人的鰭回來給湖畔鎮的碼頭管理員巴倫。"}},
[151] = {"可憐的老布蘭契", {"西部荒野的弗娜·法布隆要你帶８捧燕麥給她。"}},
[152] = {"清理海岸", {"殺死7名魚人潮行者、7名魚人戰士、7名魚人智者，還有7名魚人灘行者，然後回去找西部荒野燈塔中的葛瑞森船長。"}},
[153] = {"紅色皮面罩", {"帶15條紅色皮質面罩回來給哨兵嶺的哨兵加里安。"}},
[154] = {"歸還梳子", {"把幽靈的梳子拿回去給夜色鎮的伊娃夫人。"}},
[155] = {"迪菲亞兄弟會", {"護送迪菲亞叛徒前往迪菲亞兄弟會的秘密藏身處。一旦迪菲亞叛徒把你帶到范克里夫和他的手下的藏匿地點之後，儘快回去向格萊恩·斯托曼彙報相關資訊。"}},
[156] = {"收集腐敗之花", {"收集８個腐敗之花，然後交給夜色鎮的旅店老闆史密茲。"}},
[157] = {"幽靈的發絲", {"把幽靈的髮絲交給亞伯克隆比，他住在烏鴉嶺墓園北邊的房子裡。"}},
[158] = {"殭屍汁", {"和旅店老闆史密茲談話。"}},
[159] = {"殭屍汁", {"把殭屍汁交給烏鴉嶺墓園北方小屋裡的亞伯克隆比。"}},
[160] = {"給鎮長的字條", {"把亞伯克隆比的信交給夜色鎮的艾羅·埃伯洛克鎮長。"}},
[161] = {"水壩危機", {"總工程師辛德維爾要你把怪味粉末交給丹莫德的炸藥專家阿胥蘭·暗石。"}},
[163] = {"烏鴉嶺", {"查出是什麼東西在烏鴉嶺搞鬼。"}},
[164] = {"給斯溫的物資", {"送補給物資給斯溫。"}},
[165] = {"隱士", {"去烏鴉嶺墓園附近的小屋查看老人的情況。"}},
[166] = {"迪菲亞兄弟會", {"殺死艾德溫·范克里夫，把他的頭交給格萊恩·斯托曼。"}},
[167] = {"我的兄弟…", {"將工頭希斯耐特的探險者協會徽章帶回去給暴風城的維爾德·希斯耐特。"}},
[168] = {"收集記憶", {"找回4張礦業工會會員卡並送回給暴風城的維爾德·薊草。"}},
[169] = {"懸賞：加塞爾佐格", {"殺死加塞爾佐格並將他的頭顱帶回來交給湖畔鎮的所羅門鎮長。"}},
[170] = {"新的威脅", {"巴爾林·霜錘要你去殺死6個石齶穴居怪和6個壯實的石齶穴居怪。"}},
[173] = {"森林裡的狼人", {"為夜色鎮的卡洛爾殺掉6個夜行織影狼人。"}},
[174] = {"觀星", {"夜色鎮的維克托·安特拉斯要你給他一根青銅管。"}},
[175] = {"觀星", {"找到瑪麗，說服她借給你一個反光鏡，用於維克托的計畫。"}},
[176] = {"通緝：「霍格」", {"殺死豺狼人霍格，把他那巨大的豺狼人爪帶給治安官杜漢。"}},
[177] = {"觀星", {"從瘋狂的食屍鬼那裡拿回盲眼瑪麗的單眼透鏡，把它交給夜色鎮的維克托。"}},
[178] = {"塞歐克瑞圖斯的墜飾", {"暗淡的暗皮墜飾帶給法師塞歐克瑞圖斯。"}},
[179] = {"矮人的交易", {"斯登·粗臂想要8塊硬狼肉。"}},
[180] = {"通緝：范高雷中尉", {"殺死范高雷並將他的手掌割下，向湖畔鎮的所羅門鎮長覆命。"}},
[181] = {"觀星", {"在暮色森林南部的巨魔土丘上找到札克烏爾，把他的單片眼鏡帶回夜色鎮交給維克托。"}},
[182] = {"食人妖洞穴", {"格瑞林·白鬚要你去殺掉14個小霜鬃食人妖。"}},
[183] = {"獵殺野豬", {"塔林·銳眼讓你去殺掉12隻小型峭壁野豬。"}},
[184] = {"法布隆的地契", {"把法布隆的地契交給農夫法布隆。"}},
[185] = {"獵虎大師", {"奈辛瓦里遠征隊的艾耶克·羅歐克要求你殺死10隻小荊棘谷猛虎。"}},
[186] = {"獵虎大師", {"奈辛瓦里探險隊的艾耶克·羅歐克要你去殺死10隻荊棘谷猛虎。"}},
[187] = {"獵虎大師", {"奈辛瓦里遠征隊的艾耶克·羅歐克要你去殺死10隻老年荊棘谷猛虎。"}},
[188] = {"獵虎大師", {"奈辛瓦里探險隊的艾耶克·羅歐克要你去殺死辛達爾並帶回牠的爪子。"}},
