[190] = {"獵豹大師", {"奈辛瓦里遠征隊的艾爾加丁爵士要你去殺死1０隻小獵豹。"}},
[191] = {"獵豹大師", {"奈辛瓦里探險隊的艾爾加丁爵士要你去殺死10隻黑豹。"}},
[192] = {"獵豹大師", {"奈辛瓦里探險隊的艾爾加丁爵士要你去殺死10隻深喉獵豹。"}},
[193] = {"獵豹大師", {"奈辛瓦里遠征隊的艾爾加丁爵士要求你殺死巴爾瑟拉，並帶回它的牙。"}},
[194] = {"獵龍", {"赫米特·奈辛瓦里要求你殺死10隻荊棘谷迅猛龍。"}},
[195] = {"獵龍", {"赫米特·奈辛瓦里要你去殺死1０隻鞭尾迅猛龍。"}},
[196] = {"獵龍", {"赫米特·奈辛瓦里要求你殺死10隻叢林捕獵者。"}},
[197] = {"獵龍", {"赫米特·奈辛瓦里要求你殺死荊棘谷中最危險最狡猾的迅猛龍泰希斯。"}},
[198] = {"送補給物資給士兵索爾森", {"將各式各樣的哥布林補給品交給士兵索爾森。"}},
[199] = {"水壩危機", {"回去見主工程師辛德維爾七世，把你找到的線索交給他。"}},
[200] = {"書呆子赫羅德", {"找到書呆子赫羅德的檔案。"}},
[201] = {"調查營地", {"找到獵人營地並向藏寶海灣的克拉茲克報告這個營地的位置。"}},
[202] = {"庫爾森上校", {"殺掉6名庫爾森精英和4名庫爾森副首領，並將庫爾森的頭顱交給反抗軍營地裡的多倫上尉。"}},
[203] = {"以彼之道還施彼身", {"殺死15名庫爾森叢林戰士，然後向反抗軍營地的尤瓦中士覆命。"}},
[204] = {"庫爾森的藥物", {"給反抗軍營地裡的尤瓦中士帶回7份密林藥劑和1份毒草汁液。"}},
[205] = {"食人妖巫術", {"給叛軍營地的尼麥茲修士帶回4只劈顱食人妖的神像。"}},
[206] = {"麥佐斯", {"將心靈之眼交給反抗軍營地裡的尼麥茲修士。"}},
[207] = {"庫爾森的秘密", {"找到4塊石板並將上面的內容帶回去交給尼麥茲修士。"}},
[208] = {"王牌獵人", {"赫米特·奈辛瓦里要求你將虎王邦加拉西的頭帶回來給他。"}},
[209] = {"劈顱食人妖的獠牙", {"給藏寶海灣的科博克帶回18根劈顱食人妖的獠牙。"}},
[210] = {"克拉茲克的烹調鍋", {"把克拉茲克的烹調鍋帶給藏寶海灣的哥布林克拉茲克。"}},
[212] = {"冷餐會", {"殺死一隻冷眼蜥蜴，取一塊冷蜥蜴肉並把它帶給「藍色隱士」旅店裡的安古斯·斯特恩。","","<如果你在任務過程中死亡則任務失敗>"}},
[213] = {"惡性競爭", {"給藏寶海灣的科博克帶回8塊打磨過的水晶。"}},
[214] = {"紅色絲質面罩", {"給哨兵嶺哨塔的哨兵瑞爾帶回10條紅色絲質面罩。"}},
[215] = {"叢林中的秘密", {"與反抗軍營地裡的多倫上尉談話。"}},
[216] = {"薊皮熊怪的麻煩", {"殺死12個薊皮復仇者和12個薊皮薩滿。他們大部分都位於左拉姆海岸東部的薊皮村裡。任務完成後回到梣谷左拉姆加前哨站的卡拉恩·阿瑪卡那裡覆命。"}},
[217] = {"保衛國王的領土", {"殺掉穴居怪首領格勞姆格及他的兩個護衛，納什爾和布勞勒爾。然後回到南部警戒塔向拉格弗斯上尉報告。"}},
[218] = {"被竊取的日記", {"格瑞林·白鬚要你去殺掉冷酷的格瑞克尼爾，並取回他的日記。"}},
[219] = {"失蹤人員", {"保護基沙恩下士回到赤脊。"}},
[220] = {"水之召喚", {"把最純淨的水交給貧瘠之地的伊斯倫。"}},
[221] = {"森林裡的狼人", {"為夜色鎮的卡洛爾殺掉12個夜行黑暗狼人。"}},
[222] = {"森林裡的狼人", {"為夜色鎮的卡洛爾殺掉8個夜行邪齒狼人和8個夜行墮落狼人。"}},
[223] = {"森林裡的狼人", {"把卡洛爾的便箋交給喬納森·卡爾文。"}},
[224] = {"保衛國王的領土", {"南部警戒塔的巡山人庫伯弗林特要你殺掉10個碎石穴居怪和10個碎石怪斥候。"}},
[225] = {"飽經風霜的墓碑", {"去和夜色鎮的希拉·沃甯迪談話。"}},
[226] = {"惡狼成群", {"殺掉12只饑餓的恐狼和8隻瘋狂的恐狼，然後到斯溫的營地中向拉爾斯交差。"}},
[227] = {"摩根·拉迪莫爾", {"去和夜色鎮的指揮官阿勒泰婭·埃伯洛克談話。"}},
[228] = {"摩拉迪姆", {"殺掉摩拉迪姆，把他的頭骨交給夜色鎮的指揮官阿勒泰婭·埃伯洛克。"}},
[229] = {"倖存的女兒", {"去和夜色鎮的守夜人莎拉·拉迪莫爾談話。"}},
[230] = {"斯溫的營地", {"把你從斯溫的農場找到的書交給他。"}},
[231] = {"女兒的愛", {"把莎拉·拉迪莫爾的戒指拿到摩根·拉迪莫爾的墳墓上去。"}},
[232] = {"金格的貨物", {"把訂貨單交給幽暗城的奧雷薩多·盧卡。"}},
[233] = {"寒脊山谷的送信任務", {"把這一疊信件送給塔林·銳眼。"}},
[234] = {"寒脊山谷的送信任務", {"把這封信送給格瑞林·白鬚。"}},
[235] = {"梣谷狩獵", {"與梣谷碎木崗哨的塞娜尼·雷心談話。"}},
[237] = {"保衛國王的領土", {"南部警戒塔的巡山人格拉維戈要你殺掉10個碎石怪擊顱者和10個碎石怪先知，然後回去向他彙報。"}},
[238] = {"金格的貨物", {"把採樣工具包交給幽暗城的藥劑師金格。"}},
[239] = {"西泉要塞", {"到西泉要塞去和瑞尼爾副隊長談話。"}},
[240] = {"基特斯的美餐", {"把黑蟹蛋糕拿回去交給基特斯。"}},
[243] = {"進入沙漠", {"和加基森的首席工程師沙克斯·比格維茲談一談，請他為實驗工具包提供能量源。"}},
[244] = {"豺狼人的入侵", {"找到菲爾頓副隊長。"}},
[245] = {"蜘蛛的威脅", {"守夜人道茨要你殺15隻小型結網毒蜘蛛。"}},
[246] = {"審時度勢", {"殺死10個混血赤脊山豺狼人和6個赤脊山偷獵者，然後向湖畔鎮的菲爾頓副隊長覆命。"}},
[247] = {"完成狩獵", nil},
[248] = {"監視", {"爬上石望要塞一旁的哨塔。","","為阿祖拉的銘文飾品找一個合適的容器。"}},
[249] = {"莫甘斯", {"擊敗莫甘斯。","","將他的陰影墜飾帶給塞歐克瑞圖斯，他就在艾爾文森林內的阿祖拉之塔中。"}},
[250] = {"水壩危機", {"查看水壩東邊斜坡附近的區域，調查一下黑鐵矮人準備做什麼，然後把線索帶給主工程師辛德維爾七世．"}},
[251] = {"翻譯亞伯克隆比的信", {"把寫給艾爾羅的信拿給希拉·沃寧迪。"}},
[252] = {"翻譯好的信件", {"把翻好的信帶給艾爾羅·埃伯洛克公爵。"}},
[253] = {"藏屍者的妻子", {"找到伊莉莎的墳墓，從她的身上取回藏屍者的心臟，把它交給艾爾羅·埃伯洛克。"}},
[254] = {"掘墓", nil},
[255] = {"雇傭兵", {"塞爾薩瑪的鎮長埃羅恩·鈍鼻雇你去殺掉4個莫格羅什巨魔、4個莫格羅什蠻兵和4個莫格羅什執行者。"}},
[256] = {"通緝令：卓克蘇爾", {"殺了卓克蘇爾，把他的頭顱帶給塞爾薩瑪的鎮長埃羅恩·鈍鼻。"}},
[257] = {"自豪的獵人", {"殺死6隻山鷲，然後回到旅行者營地見年輕的達瑞爾，時限為15分鐘。"}},
[258] = {"獵人的挑戰", {"殺掉5隻老山豬，然後回到旅行者營地去見年輕的達瑞爾，時限為12分鐘。"}},
[261] = {"血色之路", {"殺掉30個不死族劫掠者，然後向尼耶爾前哨站的安東修士覆命。"}},
[262] = {"模糊的人影", {"帶著你從斯溫的農場找到的書，把它拿給夜色鎮上的人看看。"}},
[263] = {"保衛國王的領土", {"南部警戒塔的巡山人沃爾班要你殺掉10個碎石怪薩滿和10個碎石怪斷骨者。"}},
[264] = {"直到死亡把我們分離", {"把克拉莉斯的墜飾放在銀松森林尤瑞夫的墳墓上。"}},
[265] = {"繼續搜尋", {"看看其他的鎮民有沒有關於模糊的人影的線索。"}},
[266] = {"調查旅店", {"到旅店去查一查關於模糊人影的線索。"}},
[267] = {"穴居怪的威脅", {"給南部警戒塔的拉格弗斯上尉帶去8顆穴居怪的石牙。"}},
[268] = {"回覆斯溫", {"把基特斯的日記交給斯溫。"}},
[269] = {"尋求指引", {"把基特斯的日記交給暴風城的主教法席恩。"}},
[270] = {"被詛咒的艦隊", {"到濕地的米奈希爾港去，找戈羅林·鋼眉談話。"}},
[271] = {"維林的報復", {"殺掉奧爾蘇迪，把它的頭顱帶給旅行者營地裡的達瑞爾。"}},
[272] = {"海獅試煉", {"尋找水獸耐力墜飾和水獸敏捷墜飾。與月光林地的居民談話，找出這些東西可能被放在哪裡。","","在雷姆洛斯神殿附近將海獅墜飾的兩部分合而為一。","","將合併好的墜飾交給月光林地永夜港中的德迪利特·星焰。"}},
[273] = {"挖掘場的補給品", {"和胡達爾談話。"}},
[274] = {"水壩危機", {"阿胥蘭·暗石要你回去見主工程師辛德維爾七世，把有關這種炸藥的新發現告訴他。"}},
[275] = {"大地上的膿皰", {"殺死12隻沼澤爬行者，然後向濕地的綠色守衛者雷希耶爾覆命。"}},
[276] = {"踐踏之爪", {"殺死15名蘚皮豺狼人和10名混血蘚皮豺狼人，然後向濕地的綠色守衛者雷希耶爾覆命。"}},
[277] = {"火焰管制", {"給綠色守衛者雷希耶爾帶回9塊粗製打火石。"}},
[278] = {"水壩危機", {"主工程師辛德維爾七世要你收集一份潛伏者的毒液，一塊莫格羅什水晶和一滴鱷魚的眼淚。"}},
[279] = {"海中的魚人", {"殺掉12個藍腮魚人。","","殺掉高布勒爾並砍下它的頭。","","將高布勒爾的頭顱交給米奈希爾港的卡爾·波蘭。"}},
[280] = {"水壩危機", {"主工程師辛德維爾七世要你遊到水壩底部，找到裝著炸藥的木桶，然後把拆彈劑放進去，阻止將要發生的爆炸。"}},
[281] = {"奪回雕像", {"搜索海邊魚人村落中的木箱和木桶。"}},
[282] = {"森內爾的觀察站", {"和巡山人泰洛斯談話。"}},
[283] = {"水壩危機", {"拆彈劑看來已經產生了效果。你可以回去向主工程師辛德維爾七世彙報這個好消息了。"}},
[284] = {"繼續搜尋", {"搜索米奈希爾雕塑。"}},
[285] = {"搜尋雕像", {"繼續在魚人村落中搜尋米奈希爾雕像的蹤跡。"}},
[286] = {"歸還雕像", {"將米奈希爾雕像還給卡爾·波蘭。"}},
[287] = {"霜鬃要塞", {"偵查霜鬃要塞，替卡拉諾斯的森內爾·白鬚殺掉5個霜鬃獵頭者。"}},
[288] = {"第三艦隊", {"為大副菲茲莫斯買一份壺裝蜜酒。"}},
[289] = {"被詛咒的船員", {"殺死13個被詛咒的水手、5個被詛咒的水兵和大副斯涅利格。把斯涅利格的鼻煙盒交給米奈希爾港的大副菲茲莫斯。"}},
[290] = {"解除詛咒", {"從哈林多爾船長那裡拿到無畏號的保險箱鑰匙。","","用鑰匙打開無畏號上鎖的保險箱。"}},
[291] = {"森內爾的報告", {"把森內爾的報告交給鐵爐堡的參議員巴林·紅石。"}},
[292] = {"帕雷斯之眼", {"把被詛咒的帕雷斯之眼交給戈羅林·鋼眉。"}},
[293] = {"淨化帕雷斯之眼", {"把被詛咒的帕雷斯之眼交給大主教本尼迪塔斯，他就在暴風城的聖光大教堂裡。"}},
[294] = {"奧莫爾的復仇", {"維爾加挖掘場的奧莫爾·鐵衣要求你殺死10隻雜斑迅猛龍和10隻雜斑尖嘯龍。"}},
[295] = {"奧莫爾的復仇", {"奧莫爾‧鐵衣要求你殺死10隻雜斑鐮爪龍和10隻雜斑刺喉龍，然後回到維爾加挖掘場向他覆命。"}},
[296] = {"奧莫爾的復仇", {"維爾加挖掘場的奧莫爾·鐵衣要求你殺死薩爾圖斯，並在任務完成之後帶著它的一隻爪子向他覆命。"}},
[297] = {"收集石像", {"收集8個小石像，把它們交給麥格瑪爾·落斧。"}},
[298] = {"挖掘進度報告", {"把鐵環挖掘場的進度報告帶給塞爾薩瑪的吉恩·角盔。"}},
[299] = {"發現歷史", {"勘察員維爾加要求你在挖掘場中搜索4塊石板的碎片，它們是阿度斯碎片、莫德爾碎片、高爾姆碎片和奈爾魯碎片。"}},
[301] = {"向鐵爐堡報告", {"把鐵環挖掘場的進度報告交給勘察員塔伯斯·雷矛。"}},
[302] = {"鐵環的火藥", {"和塞爾薩瑪的吉恩·角盔談話。"}},
[303] = {"黑鐵戰爭", {"丹莫德的莫特雷‧加瑪森要求你殺死15名黑鐵矮人、5名黑鐵隧道工、5名黑鐵破壞者和5名黑鐵爆破兵。"}},
[304] = {"艱鉅的任務", {"殺死邪惡的巴爾加拉斯，把他的耳朵帶給丹莫德外的布萊德·長鬚。"}},
[305] = {"尋找挖掘隊", {"塔雷爾·石紋要求你到挖掘場裡去找到麥琳·石紋。"}},
[306] = {"尋找挖掘隊", {"把麥琳的信件交給塔雷爾·石紋覆命。"}},
[307] = {"骯髒的爪子", {"到銀泉礦坑去收集4套礦工裝備，然後向巡山人卡爾·雷矛覆命。"}},
[308] = {"加文的愛好", nil},
[309] = {"護送貨物", {"確保把米蘭和貨物送到挖掘場，然後通知勘察員基恩薩·鐵環。"}},
[310] = {"針鋒相對", {"到卡拉諾斯的雷酒釀製廠酒窖裡去，把一桶雷霆啤酒換成熱麥酒。"}},
[311] = {"向馬萊斯回報", {"把雷霆麥酒交給烈酒村的馬萊斯·麥酒。"}},
[312] = {"馬克格拉恩的乾肉", {"從冰鬚的洞穴裡拿回裝有馬克格拉恩的乾肉的儲藏櫃。"}},
[313] = {"灰色洞穴", {"收集8束雪怪的鬃毛，把它們交給駕駛員迪恩·石輪。"}},
[314] = {"保護牲畜", {"山羊農場的魯德拉·凍石要你殺了瓦加什，並且把它的牙齒給她帶回去。"}},
[315] = {"完美烈酒", {"收集6束微光草，把它們交給烈酒村的雷傑德·麥酒。"}},
[317] = {"貝爾丁的補給", {"收集4大塊野豬肉和2張厚熊皮，把它們交給鋼架補給站的駕駛員貝隆·風箱。"}},
[318] = {"艾沃沙酒", {"從烈酒村的雷傑德·麥酒那里弄到一桶艾沃沙酒。"}},
[319] = {"艾沃沙酒", {"殺掉6頭冰爪熊、8隻老峭壁野豬和8隻雪豹，然後回到烈酒村的雷傑德·麥酒那裡。"}},
[320] = {"艾沃沙酒", {"把這桶艾沃沙酒交給鋼架補給站的駕駛員貝隆·風箱。"}},
[321] = {"光鑄鐵", {"搜索飛翔魚鷹號的殘骸。"}},
[322] = {"格瑞曼德·艾爾默", {"將這箱光鑄鐵錠交給格瑞曼德·艾爾默。"}},
[323] = {"證明你的實力", {"殺掉15個骷髏襲擊者、3個骷髏醫師和3個骷髏看守，然後回來見斯溫。"}},
[324] = {"丟失的鐵錠", {"收集5塊光鑄鐵錠，把它們交給濕地的戈羅林·鋼眉。"}},
[325] = {"整裝待發", {"現在你已經得到了強大的武器，去向暮色森林的斯溫覆命吧。"}},
[328] = {"隱藏的鑰匙", {"使用黃銅鑰匙打開書呆子赫羅德的保險箱。"}},
[329] = {"找出內鬼！", {"將沾泥的便箋交給叛軍營地裡的多倫上尉。"}},
[330] = {"巡邏時間表", {"與塞斯曼下士談話。"}},
[331] = {"向多倫報告", {"與多倫上尉談話。"}},
[332] = {"酒店的廣告", {"到加林納酒店去, 將酒票交給蘇澤塔·加林納以換一瓶免費的酒。"}},
[333] = {"哈蘭需要供貨", {"找到運河裁縫店，並將哈蘭·巴格雷的布料訂單帶給雷瑪·施涅德。"}},
[334] = {"薩爾曼的針線包", {"到暴風城法師區的拉爾森服裝店去，將針線包帶給薩爾曼·斯涅德。"}},
[335] = {"名釀", {"黑爪加爾德斯要求你從夜色鎮給他摘1朵蒂羅亞之淚，再從濕地給他采一塊麝鼠根。"}},
[336] = {"名釀", {"將黑爪烈酒帶給祈願廳裡的維沙克公爵。"}},
[337] = {"一本破舊的歷史書", {"把《暴風城的歷史》這本書還給暴風城圖書館。"}},
[338] = {"荊棘谷的青山", {"收集《荊棘谷的青山》的手稿中丟失的頁面。在集齊四章書之後，將它們還給巴尼爾·石罐。"}},
[339] = {"荊棘谷的青山 - 第一章", {"將奈辛瓦里的小說《荊棘谷的青山》的第1頁，第4頁，第6頁和第8頁帶給巴尼爾·石罐以湊齊第一章。"}},
[340] = {"荊棘谷的青山 - 第二章", {"將奈辛瓦里的小說《荊棘谷的青山》的第10頁，第11頁，第14頁和第16頁帶給巴尼爾·石罐以湊齊第二章。"}},
[341] = {"荊棘谷的青山 - 第三章", {"將奈辛瓦里的小說《荊棘谷的青山》的第18頁，第20頁，第21頁和第24頁帶給巴尼爾·石罐以湊齊第三章。"}},
[342] = {"荊棘谷的青山 - 第四章", {"將奈辛瓦里的小說《荊棘谷的青山》的第25頁，第26頁和第27頁帶給巴尼爾·石罐以湊齊第四章。"}},
[343] = {"關於堅韌的演講", {"到暴風城堡的皇家圖書館去與密爾頓·西弗交談，他將會為你找到克里斯多夫修士所需要的關於冶金學的書。"}},
[344] = {"帕克斯頓修士", {"與北郡修道院的帕克斯頓修士談話。"}},
[345] = {"墨水補給", {"與湖畔鎮的工頭奧斯洛交談，並向他要一些瑞斯班鐵礦石。"}},
[346] = {"克里斯多夫的書", {"回到教堂廣場，將《金屬的延展性》交給克里斯多夫修士。"}},
[347] = {"瑞斯班礦石", {"收集5袋瑞斯班礦石，把它們帶給北郡圖書館的帕克斯頓修士。"}},
[348] = {"荊棘谷熱疫", {"找到巫醫安巴格瓦並要求他召喚出野人莫克，然後將野人莫克的心臟交給芬·菲茲拉克。"}},
[350] = {"老朋友", {"與暴風城的伊林·提亞斯談話。"}},
[351] = {"尋找OOX-17/TN！", {"把定位器帶到奧格索普的母體機器人那裡。"}},
[353] = {"雷矛的包裹", {"把給卡爾·雷矛的包裹交給洛克莫丹北部哨塔里的巡山人卡爾·雷矛。"}},
[354] = {"阿加曼德家族", {"把格里高的遺骸、妮薩的殘骸和薩爾曼的遺骸交給布瑞爾的庫勒曼·法席恩。"}},
[355] = {"與塞弗倫交談", {"與布瑞爾的執政官塞弗倫談話。"}},
[356] = {"巡查後方", {"殺死8個可怕的血殭屍和8個遊蕩的幽靈，然後向亡靈衛兵林奈彙報。"}},
[357] = {"巫妖的身份", {"把巫妖的法術書帶給幽暗城的比索·埃斯沙德。"}},
[358] = {"盜墓賊", {"殺死腐皮盜墓賊和混血腐皮豺狼人。","","給布瑞爾的執政官塞弗倫帶回8瓶防腐劑。"}},
[359] = {"亡靈衛兵的職責", {"與亡靈衛兵林奈談話。"}},
[360] = {"向塞弗倫回報", {"向布瑞爾的執政官塞弗倫報告。"}},
[361] = {"未寄出的信件", {"找到伊維特·法席恩，將薩爾曼·阿加曼德的信交給她。"}},
[362] = {"鬧鬼的磨坊", {"殺死代弗林·阿加曼德，然後將代弗林的遺骸交給布瑞爾的庫勒曼·法席恩。"}},
[363] = {"突然醒來", {"和暗影牧師薩維斯談話。"}},
[364] = {"無腦的殭屍", {"暗影牧師薩維斯讓你殺掉8個無腦的殭屍和8個醜陋的殭屍。"}},
[365] = {"悲傷之地", {"從位於布瑞爾西邊、喪鐘鎮北邊的農場中偷10顆南瓜來，把它們交給布瑞爾的藥劑師喬漢。"}},
[366] = {"歸還書籍", {"到岡瑟爾居住的小島去歸還他的法術書。"}},
[367] = {"新的瘟疫", {"布瑞爾鎮裡的藥劑師喬漢要求你收集5瓶黑暗犬的血液。"}},
[368] = {"新的瘟疫", {"布瑞爾鎮裡的藥劑師喬漢要求你收集5片提里斯法林地的邪鰭魚人的鱗片。"}},
[369] = {"新的瘟疫", {"布瑞爾鎮裡的藥劑師喬漢要你去收集4份邪惡的夜行蜘蛛的毒液樣本。"}},
[370] = {"與血色十字軍的戰爭", {"布瑞爾的執行官塞加德要求你殺掉派瑞恩隊長、3名血色狂熱者和3名血色傳教士。"}},
[371] = {"與血色十字軍的戰爭", {"布瑞爾的執行官塞加德要求你殺掉瓦松隊長和5名血色苦行修士。"}},
[372] = {"與血色十字軍的戰爭", {"布瑞爾的執行官塞加德要求你刺殺麥拉其隊長及他的兩名保鏢。"}},
[373] = {"未寄出的信", {"將艾德溫·范克里夫的信交給巴洛斯·艾力克斯頓。"}},
[374] = {"死亡證明", {"給布瑞爾的亡靈衛兵伯吉斯帶回10枚血色十字軍徽記之戒。"}},
[375] = {"死亡之寒", {"給布瑞爾的格雷森·戴德馬帶回5張夜行蝙蝠的毛皮和一些粗線。"}},
[376] = {"被詛咒者", {"新兵艾爾雷斯需要6隻食腐狼的爪子和6隻夜行蝙蝠翼。"}},
[377] = {"罪與罰", {"夜色鎮的米爾斯迪普議員要你殺死迪克斯特·瓦德，並把他的手帶回來作為證明。"}},
[378] = {"卡姆·深怒", {"丹莫德的莫特雷·加瑪森要求你把卡姆·深怒的頭顱交給他。"}},
[379] = {"口渴的比格維茲", {"給加基森的首席工程師沙克斯·比格維茲帶去五隻廢土水袋。"}},
[380] = {"夜行蜘蛛洞穴", {"執行官阿倫要你去殺掉10隻小夜行蜘蛛和8隻夜行蜘蛛。"}},
[381] = {"血色十字軍", {"從血色信徒和血色新兵身上收集12枚血色十字軍臂章，把它們交給執行官阿倫。"}},
[382] = {"十字軍信差", {"到十字軍營地去殺掉信差邁文·考加爾，將你發現的情報交給執行官阿倫。"}},
[383] = {"重要情報", {"把血色十字軍檔案交給布瑞爾的執行官塞加德。"}},
[384] = {"啤酒烤豬排", {"卡拉諾斯的拉格納·雷酒需要6塊峭壁野豬肋排和1杯狂想麥酒。"}},
[385] = {"捕獵鱷魚", {"收集5塊鱷魚肉和6張鱷魚皮，把它們交給旅行者營地裡的馬雷克·鐵心。"}},
[386] = {"伸張正義", {"把塔高爾的頭顱帶給湖畔鎮的衛兵伯爾頓。"}},
[387] = {"鎮壓暴動", {"暴風城的典獄官塞爾沃特要求你殺死監獄中的10名迪菲亞囚犯、8名迪菲亞罪犯和8名迪菲亞叛軍。"}},
[388] = {"鮮血的顏色", {"暴風城的尼科瓦·拉斯克要你取得10條紅色毛紡面罩。"}},
[389] = {"巴基爾·斯瑞德", {"與監獄的典獄官塞爾沃特談話。"}},
[391] = {"監獄暴動", {"殺死巴基爾·斯瑞德，把他的頭帶給監獄的典獄官塞爾沃特。"}},
[392] = {"好奇的訪客", {"將神秘訪客的資料交給暴風城的巴洛斯·艾力克斯頓。"}},
[393] = {"往日的陰影", {"與舊城區的馬迪亞斯·肖爾談話。"}},
[394] = {"禽獸的首級", {"與暴風城舊城區的馬迪亞斯·肖爾談話。"}},
[395] = {"兄弟會的滅亡", {"與暴風城的巴洛斯·艾力克斯頓談話。"}},
[396] = {"覲見國王", {"將有關迪菲亞兄弟會的報告送給暴風要塞裡的國王瓦里安·烏瑞恩。"}},
[397] = {"幹得好", {"去找黑爪加爾德斯的僕人茲吉談一談，並向他索要你的酬勞。"}},
[398] = {"通緝：蛆眼", {"殺死蛆眼，並將他的爪子交給布瑞爾的執行官塞加德以換取酬勞。"}},
[399] = {"童年的記憶", {"到巴洛斯·艾力克斯頓在西部荒野的房子裡找尋他的指南針，並帶回暴風城教堂區給他。"}},
