[4762] = {"壁泉河", {"到奧伯丁的北面去，沿著壁泉河到達第一個瀑布處，從瀑布下的水潭中取出一份水樣。","","將壁泉河水樣交給奧伯丁的桑迪斯·織風。"}},
[4763] = {"黑木熊怪的墮落", {"在空的淨化碗裡盛滿奧伯丁月井的井水。","","在黑木熊怪的北部營地裡收集水果、堅果和榖物各一份。","","將水和三種食物混合起來，放置在壁泉河附近的營火邊，這樣就會召來喚引誘熊怪墮落的薩特。","","取回墮落護符，將它交給奧伯丁的桑迪斯·織風。"}},
[4767] = {"雙足飛龍", {"將10顆風巢蠍尾獅的蛋交給亂風崗的艾魯。"}},
[4770] = {"回家", {"護送波卡·雨山走出風巢，然後和白沙崗哨的莫特加·火鬃談話。"}},
[4787] = {"遠古之卵", {"將遠古之卵交給塔納利斯的葉基亞。"}},
[4811] = {"紅色水晶", {"到奧伯丁的東邊去，沿著黑海岸東部邊界的山脈尋找一顆巨大的紅色水晶，然後向奧伯丁的哨兵戈琳達·納希恩彙報你的發現。"}},
[4812] = {"清洗水晶", {"在奧伯丁月井中把空水瓶裝滿，然後調查黑海岸東部山脈的紅水晶。"}},
[4813] = {"水晶中的碎骨", {"向奧伯丁的哨兵哨兵戈琳達·納希恩報告你的發現。"}},
[4821] = {"異型卵", {"把異型卵交給亂風崗的哈加爾·雷蹄。"}},
[4841] = {"清除半人馬", {"殺掉12個加拉克斥候、10個加拉克爭鬥者和6個加拉克逐風者，然後向亂風崗的峭壁衛兵圖林·長角覆命。"}},
[4865] = {"狂熱之蛇", {"向莫特加·火鬃彙報你的發現。"}},
[4881] = {"暗殺計畫", {"將暗殺計畫通知給白沙崗哨的卡納提·灰雲。"}},
[4904] = {"終獲自由", {"護送拉克塔·風歌離開恐怖圖騰營地，然後與亂風崗的薩利亞談話。"}},
[4921] = {"在戰鬥中失蹤", {"找到曼寇里克的妻子，然後回到十字路口找他。"}},
[4961] = {"奧拉赫寶珠的淨化", {"殺死寶珠之魔，然後與塔貝薩談話。"}},
[4962] = {"地獄犬的靈魂", {"帶上地獄犬紅寶石到淒涼之地去，用它捕獲一隻地獄犬的靈魂。成功之後，將地獄犬紅寶石和被禁錮的地獄犬靈魂交給貧瘠之地的梅納拉·沃倫德。"}},
[4963] = {"地獄火的靈魂", {"帶上地獄火綠寶石到淒涼之地去，用它捕獲一個地獄火的靈魂。成功之後，將地獄火綠寶石和被禁錮的地獄火靈魂交給貧瘠之地的梅納拉·沃倫德。"}},
[4964] = {"達奧拉赫寶珠", {"等待梅納拉·沃倫德完成達奧拉赫寶珠，然後再與她談一談。"}},
[4966] = {"保護卡納提·灰雲", {"保護卡納提·灰雲免受半人馬的襲擊。"}},
[4968] = {"奧拉赫寶珠", {"與貧瘠之地的梅納拉·沃倫德談話。"}},
[4969] = {"奧拉赫寶珠", {"與貧瘠之地的梅納拉·沃倫德談話。"}},
[4976] = {"歸還淨化過的寶珠", {"將淨化過的地獄火寶珠交給貧瘠之地的梅納拉·沃倫德。"}},
[5041] = {"十字路口的補給物資", {"找到並把十字路口的補給箱還給貧瘠之地的索克。"}},
[5042] = {"阿迦瑪甘的力量", nil},
[5043] = {"阿迦瑪甘的敏捷", nil},
[5044] = {"阿迦瑪甘的智慧", nil},
[5045] = {"高漲的士氣", nil},
[5046] = {"野豬之皮", nil},
[5052] = {"阿迦瑪甘的血岩碎片", {"給陶拉祖營地的碎牙帶去一塊血岩碎片。","","如果你想要他賜予你阿迦瑪甘的力量，就搜集更多的血岩碎片。"}},
[5061] = {"水棲形態", {"回到達納蘇斯，讓瑪斯雷·馭熊者看看你的海獅墜飾。"}},
[5062] = {"聖火", {"採集10支火岩龍舌蘭，然後去雷霆崖的長者高地尋找瑪加薩·恐怖圖騰。"}},
[5064] = {"偵察恐怖圖騰族", {"在暗雲峰找出並拿回三封秘密訊息。"}},
[5088] = {"阿利卡拉", {"殺死阿利卡拉。把她的遺體和火岩粉交給白沙崗哨的莫特加‧火鬃作為證明。"}},
[5147] = {"通緝：阿納克‧恐怖圖騰", {"殺死阿納克·恐怖圖騰，並向亂風崗的峭壁衛兵圖林·長角出示證據。"}},
[5151] = {"超適應齒輪", {"殺了那隻野獸並把超適應齒輪和豹籠鑰匙帶回來交給維茲羅。"}},
[5261] = {"伊根·派特斯金納", {"與伊根·派特斯金納談話。"}},
[5301] = {"護甲鍛造師的藝術", {"要想成為一名護甲鍛造師的話，你必須將下列物品交給奧克索斯：4頂華麗秘銀頭盔、2雙華麗秘銀戰靴和1副華麗秘銀胸甲。"}},
[5321] = {"昏昏欲睡", {"護送克羅尼亞‧恒影沿著道路向南前往利拉迪斯‧月河那裡，並在黑海岸尋找他的背包。"}},
[5361] = {"族譜", {"將峭壁衛兵圖林·長角的報告交給淒涼之地鬼旅崗哨的納塔卡·長角。"}},
[5381] = {"埃盧梭斯之手", {"在雷斧堡壘中找到惡魔之盒，把它和惡魔之鋤一起交給葬影村的泰迦·慧鬃。"}},
[5386] = {"食魚度日", {"與葬影村的吉納澤林談話，然後將2條血肚魚交給納塔卡·長角。"}},
[5421] = {"坐享其成", nil},
[5441] = {"懶惰的苦工", {"在懶惰的苦工睡覺時，用工頭的木棒敲他們。敲醒5個苦工，然後把工頭的木棒還給試煉谷的工頭塔茲利爾。"}},
[5481] = {"葛爾多的任務", {"收集3根陰暗草，把它們交給布瑞爾墓地的初級藥劑師霍蘭德。"}},
[5482] = {"末日草", {"收集10株末日草，把它們交給初級藥劑師霍蘭德。"}},
[5501] = {"集骨者", {"從科多墓地收集10根科多獸骨，把它們交給獸人小屋的比布里·弗斯巴克。"}},
[5541] = {"海格納的彈藥", {"把海格納的彈藥交給丹莫洛的海格納·重槍。"}},
[5545] = {"木材危機", {"收集8捆木材，把它們交給東谷伐木場的管理員萊琳。"}},
[5561] = {"誘捕科多獸", {"將科多獸誘引器和5頭被馴服的科多獸交給瑟卡布斯庫的營地中的斯米德·瑟卡布斯庫。"}},
[5581] = {"燃燒軍團的傳送門", {"放逐6個瑪諾洛克集會所的傳送門，然後回到葬影村的泰迦·慧鬃那裡。"}},
[5621] = {"月光之衣", {"找到哨兵莎恩雅並使用次級治療術（等級 2）來治療她。然後對她施放真言術：韌，最後向多蘭納爾的勞爾娜·晨光覆命。"}},
[5622] = {"月神的恩賜", {"與泰達希爾的勞爾娜·晨光談話。"}},
[5623] = {"聖光的恩賜", {"與艾爾文森林的女牧師潔塞塔談話。"}},
[5624] = {"聖光之衣", {"找到衛兵羅伯茲並使用次級治療術（等級 2）治療他。然後對他施放真言術：韌，之後回來找閃金鎮的女牧師潔塞塔。"}},
[5625] = {"聖光之衣", {"找到巡山人多爾夫並使用次級治療術（等級 2）治療他。然後對他施放真言術：韌，之後回去找卡拉諾斯的馬克薩恩·安沃爾。"}},
[5626] = {"聖光的恩賜", {"與丹莫洛的馬克薩恩·安沃爾談話。"}},
