[5635] = {"絕望禱言", {"與鐵爐堡的高階牧師洛漢交談。"}},
[5654] = {"虛弱妖術", {"與奧格瑪的烏爾庫談話。"}},
[5658] = {"虛弱之觸", nil},
[5673] = {"伊露恩的賜福", {"與達納蘇斯的女祭司阿蘭希雅談話。"}},
[5676] = {"秘法回饋", nil},
[5713] = {"見一個殺一個", {"保護哨兵阿娜莎，然後向梣谷邁斯特拉崗哨的奧奈雅報告。"}},
[5722] = {"尋找背包", {"在怒焰裂谷搜尋瑪爾·恐怖圖騰的屍體以及他留下的東西。"}},
[5723] = {"試探敵人", {"在奧格瑪找到怒焰裂谷，殺掉8個怒焰穴居怪和8個怒焰薩滿，然後向雷霆崖的拉哈羅覆命。"}},
[5724] = {"歸還背包", {"將恐怖圖騰背包交給雷霆崖的拉哈羅。"}},
[5725] = {"毀滅之力", {"將《暗影法術研究》和《扭曲虛空的魔法》這兩本書交給幽暗城的瓦里瑪薩斯。"}},
[5726] = {"隱藏的敵人", {"將軍官的徽章交給奧格瑪的索爾。"}},
[5727] = {"隱藏的敵人", {"將軍官的徽章交給尼爾魯·燃刃並與他談話，看看他是否相信你是燃刃氏族中的一員，然後回到奧格瑪的索爾那裡。"}},
[5728] = {"隱藏的敵人", {"殺死巴札蘭和祈求者耶戈什，然後回到奧格瑪的索爾那裡。"}},
[5729] = {"隱藏的敵人", {"與奧格瑪的尼爾魯·火刃談話。"}},
[5730] = {"隱藏的敵人", {"與奧格瑪的索爾談話，告訴他你瞭解到的東西。"}},
[5741] = {"聖光節杖", {"拿到聖光節杖，並將它交給艾瑟雷索塔里的阿佐爾·奧達蒙特。"}},
[5761] = {"饑餓者塔拉加曼", {"進入怒焰裂谷，殺死饑餓者塔拉加曼，然後把他的心臟交給奧格瑪的尼爾魯·火刃。"}},
[5762] = {"赫米特·奈辛瓦里", {"將克拉維爾的箱子送到荊棘谷的赫米特·奈辛瓦里那裡。"}},
[5763] = {"荊棘谷狩獵", {"將魯恩的科多獸角送到荊棘谷的赫米特·奈辛瓦里那裡。"}},
[5821] = {"雇傭保鏢", {"護送基澤爾頓商隊通過科卡爾半人馬村，然後與瑟卡布斯庫的營地中的斯米德談話以領取你的獎賞。"}},
[5863] = {"砂槌巨魔", {"加基森的安迪·利恩想要你攻入砂槌營地，殺死10個砂槌蠻兵、10個砂槌執行者，以及掠奪者格瑪洛克。"}},
[5881] = {"召回衛兵", {"馬格蘭希望你將信送到貧瘠之地升降梯的瑞什·遠行者手中。"}},
[5921] = {"月光林地", {"使用法術「傳送：月光林地」抵達月光林地，在那裡與永夜港的德迪利特·星焰談話。"}},
[5923] = {"回應召喚", {"與達納蘇斯塞納里奧區的瑪斯雷·馭熊者談話。"}},
[5925] = {"回應召喚", {"與達納蘇斯塞納里奧區的瑪斯雷·馭熊者談話。"}},
[5929] = {"巨熊之靈", {"到月光林地的西北部去尋找巨熊之靈，向它學習關於熊的知識，然後回到月光林地的永夜港去找德迪利特·星焰。"}},
[5931] = {"返回達納蘇斯", {"回到達納蘇斯，與塞納里奧區的瑪斯雷·馭熊者談話。"}},
[5943] = {"基澤爾頓車隊", {"護送基澤爾頓車隊通過瑪諾洛克集會所，然後與瑟卡布斯庫的營地的斯米德談一談，領取你的獎勵。"}},
[6001] = {"身心之力", {"使用奧伯丁的月夜梟獸之石上面的塞納里奧月塵引出月爪梟獸，然後擊敗月爪梟獸並吸取它所擁有的身心之力。","","任務完成之後，與達納蘇斯的瑪斯雷·馭熊者談話。"}},
[6002] = {"身心之力", {"使用莫高雷與貧瘠之地交界處的月夜梟獸之石上面的塞納里奧月塵引出月爪梟獸，然後擊敗月爪梟獸並吸取它所擁有的身心之力。","","任務完成之後，與雷霆崖的圖拉克·符文圖騰談話。"}},
[6027] = {"上古之書", {"拿到上古之書，將其交給艾瑟雷索塔中的阿佐爾·奧達蒙特。"}},
[6062] = {"馴服野獸", {"使用馴獸棒馴服可怕的雜斑野豬。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。"}},
[6063] = {"馴服野獸", {"使用馴獸棒馴服樹林潛伏者。練習你的技能，然後將馴獸棒還給多蘭納爾的達札拉。"}},
[6064] = {"馴服野獸", {"使用馴獸棒馴服大型峭壁野豬。練習你的技能，然後將馴獸棒還給卡拉諾斯的格瑞夫。"}},
[6069] = {"獵人之道", {"與剃刀嶺的索塔爾談話。"}},
[6071] = {"獵人之道", {"與多蘭納爾的達札拉談話。"}},
[6075] = {"獵人之道", {"與卡拉諾斯的格瑞夫談話。"}},
[6081] = {"訓練野獸", {"與奧格瑪的奧瑪克談話。"}},
[6082] = {"馴服野獸", {"使用馴獸棒馴服硬甲蠍。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。"}},
[6083] = {"馴服野獸", {"使用馴獸棒馴服海浪蟹。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。"}},
