[6121] = {"新的課程", {"到月光林地去，與永夜港的德迪利特·星焰談話。"}},
[6122] = {"毒水之源", {"使用空的峭壁之泉取樣器在瀑布洞口獲得水樣本。","","將盛滿的峭壁之泉取樣器送到黑海岸奧伯丁的奧蘭達利亞·夜歌那裡。"}},
[6123] = {"收集解藥", {"收集5個地根草和12個月亮菇，把它們交給奧伯丁的奧蘭達利亞·夜歌，這樣她就可以製作解藥了。"}},
[6124] = {"消除疾病", {"對黑海岸的10頭生病的鹿使用動物醫療藥膏，以此來治療它們。從壁泉河到奧伯丁，直到最南端靠近梣谷的地區都有生病的鹿出沒。"}},
[6125] = {"解毒之術", {"回到達納蘇斯塞納里奧區的瑪斯雷·馭熊者那裡。"}},
[6126] = {"新的課程", {"到月光林地去，與永夜港的德迪利特·星焰談話。"}},
[6127] = {"毒水之源", {"使用空的鬼霧峰取樣器在山頂取水樣。","","將盛滿的鬼霧峰取樣器送到貧瘠之地十字路口的圖加·符文圖騰那裡。"}},
[6128] = {"收集解藥", {"收集5個地根草和5個科多獸角，把它們交給十字路口的圖加·符文圖騰，這樣他就可以製作解藥了。"}},
[6129] = {"消除疾病", {"對貧瘠之地北部的10隻生病的瞪羚使用動物醫療藥膏，以此來治療它們。在穿過十字路口的那條東西走向的大路北面到處都是生病的蹬羚。"}},
