[6610] = {"蚌肉大餐", {"迪爾格·奎克里弗想要你收集這些原料：","","12顆巨蛋。你可以在塔納利斯的大鵬或是其他大型鳥類那裡獲得這種蛋。","","10塊美味的蚌肉。你可以從任何蚌類身上獲得這種原料！","","20塊奧特蘭克冷酪。去買就是了！","","收集好所有原料，然後把它們交給迪爾格。"}},
[6611] = {"加基森之旅！", {"到塔納利斯沙漠的加基森去，與迪爾格·奎克里弗談談你的廚師生涯。"}},
[6612] = {"我認識一個傢伙…", {"到塔納利斯沙漠的加基森去，與迪爾格·奎克里弗談談你的廚師生涯。"}},
[6621] = {"汙林熊怪之王", {"把卡拉恩的旗子插到汙林圖騰堆中。不要讓熊怪摧毀這面旗子。擊敗穆戈特酋長，將穆戈特的圖騰交給左拉姆加的卡拉恩·阿瑪卡。"}},
[6625] = {"聯盟醫療隊", {"到塵泥沼澤的塞拉摩去，與古斯塔夫·范沃森醫生談一談關於加入聯盟外科醫療隊的事宜。"}},
[6626] = {"邪惡之地", {"殺掉8個剃刀沼澤護衛者、8個剃刀沼澤織棘者和8個亡首教徒，然後向剃刀高地入口處的麥雷姆·月歌覆命。"}},
[6627] = {"知識試煉", {"成功回答布勞格·幽魂的問題，然後和他再次對話。他會一直在石爪山等你回答問題。"}},
[6628] = {"知識試煉", {"成功回答帕科瓦·芬塔拉斯的問題，然後再次和他對話。他會一直在幽暗城等你回答問題。"}},
[6629] = {"殺死格魯迪格·暗雲", {"殺掉格魯迪格·暗雲和6個恐怖圖騰蠻兵，然後向石爪山東南面的瑪卡巴·扁蹄覆命。"}},
[6641] = {"鞭笞者沃爾沙", {"在穆格拉什尋找火盆的過程中保障他的安全，幫助他熄滅火盆，然後在與納迦作戰時保護他。","","如果你成功了，就回到左拉姆加前哨站去，把鞭笞者沃爾沙的死訊通知給戰歌傳信者。"}},
[6661] = {"捕捉礦道老鼠", {"使用捕鼠者之笛捕獲5隻礦道老鼠，把它們引到蒙提那兒去。別忘了退還笛子。"}},
