[6681] = {"拉文霍德莊園", {"把拉文霍德徽記交給拉文霍德莊園的法拉德，莊園就坐落在希爾斯布萊德的群山之中。","","你的智慧將在這次旅途中得到考驗。做好準備吧。"}},
