[7044] = {"瑪拉頓的傳說", {"找回塞雷布拉斯節杖的兩個部分：塞雷布拉斯魔棒和塞雷布拉斯鑽石。","","然後設法和塞雷布拉斯對話。"}},
[7046] = {"塞雷布拉斯節杖", {"幫助贖罪的塞雷布拉斯製作塞雷布拉斯節杖。","","當儀式完成之後再和他談談。"}},
[7064] = {"大地的污染", {"殺死瑟萊德絲公主，然後回到淒涼之地葬影村附近的瑟琳德拉那裡覆命。"}},
