[7828] = {"銀鬃捕獵者", {"辛特蘭惡齒村的獵戶馬克霍爾要求你去殺掉15頭銀鬃捕獵者和15頭銀鬃嗥狼。完成任務之後就回到他那裡覆命。","","馬克霍爾說過那些狼都躲在辛特蘭的野外。"}},
[7829] = {"野蠻的梟獸", {"辛特蘭惡齒村的獵戶馬克霍爾要求你去殺掉20頭野蠻的梟獸。完成任務之後就回到他那裡覆命。","","馬克霍爾說過那些野蠻的梟獸都躲在辛特蘭的野外。"}},
[7830] = {"死者的復仇", {"辛特蘭惡齒村的獵戶馬克霍爾要求你殺掉一頭翱翔的鋒喙獅鷲獸，並將它的獅鷲獸長羽拿回去交給他。","","馬克霍爾說過那些翱翔的鋒喙獅鷲獸就躲在辛特蘭的野外。"}},
[7833] = {"捐獻毛料", nil},
[7839] = {"邪枝竊賊", {"辛特蘭惡齒村的鐵匠斯拉提要你去找到斯拉提的工具。完成任務之後就回到他那裡去。","","你記得鐵匠斯拉提說過，你可以在辛特蘭東北部的某個邪枝食人妖神廟中找到它，要不然就是在隱匿石那邊。"}},
[7840] = {"拉爾德的午餐", {"辛特蘭惡齒村的拉爾德要求你去找到拉爾德的午餐。完成任務之後就回到他那裡去。","","拉爾德說他把午餐留在了北面的島上。當心邪枝食人妖。"}},
[7841] = {"給蠻錘部族的警告", {"辛特蘭惡齒村的奧索·莫吉克要你去殺掉15個高原前鋒、15個高原斥候、15個高原神射手和15個高原遊俠。任務完成之後回到他那裡去覆命。","","你可以在辛特蘭西北部的奎爾丹尼小屋找到那些高原精靈。"}},
[7844] = {"野蠻的親戚", {"辛特蘭惡齒村的秘法師雅爾金要你去殺掉30個邪枝割顱者和15個邪枝占卜者。任務完成之後回到他那裡去覆命。","","秘法師雅爾金說過，你可以在辛特蘭東北部的沙爾瓦薩和亞戈瓦薩神廟附近找到那些食人妖。"}},
[7845] = {"被綁架的斷齒長者！", {"辛特蘭惡齒村的斷齒族長要求你到辛薩羅去拯救她的愛人，斷齒長者。","","你聽說他被關在辛薩羅頂部，辛薩羅位於辛特蘭的南部地區，那裡是邪枝食人妖的主城。"}},
[7849] = {"分離的痛苦", {"辛特蘭惡齒村的獵戶馬克霍爾要你去找回他的雙胞胎兄弟的屍體。找到它，然後把獵戶莫克霍爾的頭顱和獵戶莫克霍爾的骨頭交給獵戶馬克霍爾。","","馬克霍爾說過，他兄弟的屍體被軟泥怪和邪枝食人妖的狼群分食。他還提到在辛薩羅有個大坑，裡面全都是軟泥怪，那裡還有個狼穴。這兩個地方都在靠近辛薩羅神廟頂部的區域。"}},
[7850] = {"黑暗之瓶", {"辛特蘭惡齒村的斷齒族長要你在辛薩羅找到10瓶腐化之血。任務完成之後就回到斷齒族長那裡。"}},
[7861] = {"通緝：邪惡祭司海克斯和她的爪牙", {"你必須殺掉邪惡祭司海克斯和20名邪枝精英守衛。任務完成之後回到辛特蘭的惡齒村，向斷齒族長報告。","","你可以在辛特蘭的邪枝食人妖城市辛薩羅的頂部找到他們。"}},
[7862] = {"職位空缺：惡齒村衛兵隊長", {"你必須消滅20個邪枝狂戰士、20個邪枝暗影獵手、20個邪枝飲血者和20個邪枝噬魂者。","","完成任務之後向辛特蘭惡齒村的斷齒族長覆命。"}},
