[8311] = {"史波普的萬鬼節糖果！", {"和暴風城、鐵爐堡、達納蘇斯的旅店老闆們及鐵爐堡的塔瓦斯德·基瑟爾交談。完成要求的惡作劇來交換他們提供的糖果。","","帶著達納蘇斯的杏仁糖、諾姆瑞根的橡皮軟糖、暴風城的奶油杏仁花生糖，和鐵爐堡的薄荷糖去找暴風城孤兒院的賈斯伯。"}},
[8365] = {"海盜的帽子！", {"塔納利斯熱砂港的傲慢的店主要你去幫他收集20頂南海海盜帽。"}},
[8366] = {"南海復仇", {"塔納利斯熱砂港的安全主管吉羅姆·比格維茲要你去幹掉10個南海海盜、10個南海劫掠者、10個南海碼頭工人和10個南海流氓。"}},
