[8370] = {"資源競賽", {"將3枚阿拉希盆地榮譽獎章交給戰場外的部落戰爭使者。"}},
[8372] = {"自然屏障", {"將3枚戰歌峽谷榮譽獎章交給戰場外的聯盟准將。"}},
