[65601] = {"痛心的愛", {"和奧格瑪的瑪加爾交談。"}},
[65602] = {"愛為何物?", {"取回木雕刻像，然後交給暴風城法師區的『黑暗縛靈師』加金。"}},
[65603] = {"誓縛", {"使用木雕刻像來召喚夢魔並加以制伏，然後將木雕刻像還給已宰的羔羊旅店的『黑暗縛靈師』加金。"}},
[65604] = {"誓縛", {"使用乾癟的圍巾來召喚夢魔，然後加以制伏，再把乾癟的圍巾交給奧格瑪的甘盧爾·血眼。"}},
[65610] = {"真希望你也在這裡", {"調查梣谷的墜星湖，然後向奧格瑪的甘盧爾·血眼回報。"}},
[76156] = {"與大地之母一同追獵", {"潛入風險投資公司在雷霆崖東南方的礦坑、從爆破補給品的推車中收集5個爆鹽採礦炸藥，並到雷霆崖將它們交給波爾頓‧暗影圖騰。"}},
[76160] = {"與大地之母一同追獵", {"在雷霆崖北側收集8個風怒果，用研缽和搗杵將它們磨碎之後，回到雷霆崖將結果告訴波爾頓‧暗影圖騰。"}},
[76240] = {"與大地之母一同追獵", {"購買或捕捉一隻新鮮的美味小魚，接著用到雷霆崖在波爾頓‧暗影圖騰面前用刀具組處理小魚。"}},
[78088] = {"奇怪的文物", {"前往梣谷的邁斯特拉崗哨，將奧薩拉克斯寶珠交給『淨化者』德爾葛蘭。"}},
[78089] = {"來自暴風城的建議", {"將奧薩拉克斯寶珠帶去給暴風城的純潔的凱薩琳。"}},
[78090] = {"多方意見", {"在暴風城內尋找術士聖所，並詢問關於珠子的事。"}},
[78091] = {"爭取你的鹽巴", {"在赤脊山的黑石召喚師身上收集 14 個召喚者之鹽，接著再回到暴風城找厄蘇拉·德林。"}},
[78092] = {"它必須被銷毀", {"從梣谷的惡魔身上收集12份瑪諾洛斯微粒。將它們和奧薩拉克斯寶珠一起帶去屠魔峽谷的瑪諾洛斯之矛處。"}},
