[79236] = {"你在想櫻桃酒嗎？", {"將櫻桃酒交給藏寶海灣的托卡，然後聽她說完剩下的故事。"}},
[79242] = {"盜卻無道", {"在阿拉希高地海岸找到伊拉里‧暮羽，然後找出她藏贓物的箱子。"}},
[79358] = {"風暴、大地和火焰", {"在阿拉希高地為維里克‧雷鎚收集5個扭曲火焰圖騰、5個扭曲大地圖騰、5個扭曲風之圖騰，以及5個扭曲水之圖騰。"}},
[79360] = {"元素援助", {"在剃刀沼澤擊敗卡爾加‧刺肋，並收集關於野豬人計畫的情報。"}},
[79361] = {"風暴、大地和火焰", {"在千針石林為普拉特‧雲眼收集5個扭曲火焰圖騰、5個扭曲大地圖騰、5個扭曲風之圖騰，以及5個扭曲水之圖騰。"}},
[79362] = {"格蘭特的盾牌", {"在烏鴉嶺墓園的其中一個骷髏身上找到格蘭特的釘錘，然後回去夜色鎮找希拉‧沃寧迪，取得更多資訊。"}},
[79363] = {"希爾薇雅的劍", {"到腐草農場擊敗7個迪菲亞夜賊和7個迪菲亞附魔師，然後回去夜色鎮找希拉‧沃寧迪，取得更多資訊。"}},
