[86576] = {"血怒飾品", {"把15個閃亮日長石帶給摩羅加爾。"}},
[86585] = {"逝者旌旗", {"揚起鐵爐堡的旌旗，呼喚穴居怪劈頭者並將其擊殺，之後去找拉格弗斯上尉回報。"}},
[86613] = {"挖掘工具", {"把6個挖掘工具還給麥格瑪爾·落斧。"}},
[86614] = {"浪潮中的絕美白銀", {"把刺著字母的銀色髮夾還給它的主人。"}},
[86667] = {"雪縛", {"將一罐雪帶去洛克湖西北岸的諾里克‧洛克賽恩自宅，並交給他本人。"}},
[86757] = {"拖延獸人", {"把6把鋸齒獸人之劍4把弧形獸人匕首交給珊蒂瑞亞。"}},
[86758] = {"痛上加痛", {"尋找並擊敗鱷魚匕牙，然後帶回馬瑞可的刀子。"}},
[86776] = {"鍛造材料", {"把10個青銅錠交給摩漢‧銅喉。"}},
[86784] = {"棍子及骸骨", {"收集6根乾樹枝並帶去給伊琳諾兒‧沙克爾頓。"}},
