[88756] = {"奪回炸藥", {"從黑鐵矮人營地取回3份偷來的炸藥。"}},
[90902] = {"尋回聖光", {"使用你的聖光術技能治療5名受傷的亡靈衛兵。"}},
[91208] = {"接受現實", {"在喪鐘鎮尋找害怕的聖騎士。"}},
[91209] = {"繼續訓練", {"沿著東邊的道路離開喪鐘鎮，找到名為布瑞爾的小鎮。向夏莉‧斯迪威爾報到，繼續你的訓練。"}},
[91282] = {"第二個家", {"尋找班達利昂要塞的堡壘，然後向那裡的布瑞頓‧山繆斯報到。"}},
[91285] = {"魚臨城下", {"殺死8個邪鰭攻擊者和8個邪鰭先知，成功後再向布瑞頓‧山繆斯回報。"}},
[91294] = {"場地導覽", {"與班達利昂要塞的居民交談。"}},
[91316] = {"維修工作", {"從提里斯法林地的暗影谷收集12個結實的木材。"}},
