[97237] = {"取書工作", {"在圖書館各處把閱讀資料找出來，然後把它們交給暴風城公園的羅伊‧路威爾斯。"}},
[97242] = {"耶爾瑪克總匯", {"從生長在榮譽谷溪流旁的香蒲和長矛草採集一些插條，然後回去耶爾瑪克鍊金術與藥劑店找考吉爾德"}},
[97243] = {"火之召喚", {"前往風莓低地的烈焰聖殿，將眠焰火炬交給歐拉里安‧迅燃。"}},
[97244] = {"火之召喚", {"到風莓低地殺死天空祭司法拉迪爾並收集法拉迪爾的心臟。"}},
[97245] = {"火之召喚", {"到申德高地找到庫拉瑪的居所，在戰鬥中擊敗它。取得勝利後，將庫拉瑪的面具交給風莓低地的歐拉里安‧迅燃。"}},
[97246] = {"美食的誘惑", {"前往博斯坦的火坑，告訴他薩托要你將米奇的午餐親自送去給米奇。"}},
[97249] = {"最喜歡的食物", {"將米奇的午餐交給葛羅瑪許堡後方的米奇"}},
[97250] = {"遭錯怪，得平反", {"在通往塵泥沼澤的邊境殺死進逼貧瘠之地的聯盟士兵，之後回到陶拉祖營地找步兵勞格瑪。"}},
[97253] = {"零件與碎片", {"從棘齒城南邊的上層海盜營地收集5把複雜的零件，之後回到棘齒城找卑鄙的維尼克斯。"}},
[97257] = {"火之召喚", {"等待歐拉里安開始在祭品火盆進行儀式，並聽從他的指示。","","你必須在倒數完畢前，將永恆之火送到瓦拉納爾。"}},
[97263] = {"你的包裹已送達", {"寄送伊德倫亂放的包裹。"}},
[97265] = {"憎恨怨怒", {"到淒涼之地的薩格隆擊敗各種怨怒薩特，然後回去葬影村找阿卡萊。"}},
[97275] = {"心急的伍特", {"將耶爾瑪克的藥水交給伍特。"}},
[97277] = {"葛朗德和戈茲溫", {"在西北方的山丘找到葛朗德和戈茲溫的營地。取回戈茲溫的機師記錄並擊殺雪豹徘徊者。"}},
[97279] = {"失而復得的武器", {"收集6把被遺棄的訓練武器，然後交給洞穴中的克贊‧荊條。"}},
[97281] = {"風暴翻騰", {"把黯淡的風暴之球拿去給枯水谷附近的雷茲拉克。"}},
[97282] = {"風暴般的潛力", {"把5個充能的雷霆蜥蜴內臟拿去給枯水谷附近的雷茲拉克。"}},
[97284] = {"瓦拉里爾的復仇", {"到淒涼之地的雷斧堡壘殺死燃刃獸人，然後回去尼耶爾前哨站找瓦拉里爾‧屠魔者。"}},
[97286] = {"研究資格", nil},
[97287] = {"精明交涉", {"在達拉然附近與大法師莫德菈的影像交談。"}},
[97288] = {"無盡的折磨", {"將可憎頭顱交給幽暗城裡的大藥劑師法拉尼爾。"}},
[97289] = {"無盡的折磨", {"到幽暗城，把男爵的頭放在歐斯瑪的遺體旁。"}},
[97290] = {"無盡的折磨", {"把你發現的事說給幽暗城的大藥劑師法拉尼爾聽。"}},
[97291] = {"無盡的折磨", {"幫幽暗城的大藥劑師法拉尼爾向貿易區的塔文‧格瑞斯特收集劇毒顱帽，在草藥學訓練師附近收集灼蝕草，以及向盜賊區的毒藥商購買苦楚精華。"}},
[97292] = {"無盡的折磨", {"幫大藥劑師法拉尼爾把嘶鳴藥水注射到歐斯瑪遺骸上的系統管道中。"}},
[97326] = {"歇腳石", {"將8個光滑巨石送去給葛羅瑪許堡後方的絲拉。"}},
[97328] = {"任何有價值之物", {"在荊棘谷的祖昆達廢墟取回8個遭竊的貨物，並把你找到的東西交給藏寶海灣的某個人。"}},
[97329] = {"鑰匙在哪裡？", {"把在荊棘谷祖昆達廢墟食人妖身上取得的鑰匙交給吉米克斯‧噴火。"}},
[97331] = {"吉米克斯大逃亡", {"護送吉米克斯‧噴火離開祖昆達廢墟，接著再把你成功的拯救任務告訴藏寶海灣的碼頭管理員羅茲基爾。"}},
[97332] = {"二度落空的信任", {"到大河林地，把二度重整包裹送給火線港的碼頭管理員惠茲巴茲。"}},
[97386] = {"格羅姆高進攻計畫", {"格羅姆高營地的指揮官阿格羅戈西要你到莫什奧格巨魔山殺死巨魔。"}},
[97453] = {"剷除雜草", {"在格羅姆高南方殺死6個肉食雜草，接著再告訴傑米爾的母親。"}},
[97485] = {"山崖傳統", {"向草藥師尼達購買一捆草藥、向附魔材料商納塔購買一捆雪松樹枝、向製皮材料商曼胡購買肌腱線，以及向烹飪材料商納爾購買儀祭燧石和火絨。","","將材料混合後，再從獵人高地將薰香灑入風中。"}},
[97530] = {"清算流沙之槌", {"塔納利斯熱砂港的安全主管吉羅姆·比格維茲要你去取回在流沙之槌巨魔營地附近弄丟的閃亮手鐲。"}},
[97534] = {"殘骸任務", {"奎因要你取回7個沙漠殘骸，然後帶回加基森給她。"}},
[97538] = {"繪畫的顏料", {"雷霆崖的塔恩‧冬蹄想要30個暗色湖的昏暗草豆莢。"}},
[97539] = {"蛛絲縫線", {"把12個手術蛛絲交給阿拉希高地落錘鎮的葛列格里‧維克多醫生。"}},
[97540] = {"綠洲", {"把平息的圖加帶回到他的妻子托爾塔身邊。"}},
[97558] = {"給被遺忘者的外皮", {"把8個夜行蝙蝠翼膜、6個黑暗犬外皮和3個邪鰭魚人皮膚帶給舍倫尼‧洛巴爾特。"}},
[97583] = {"扭扭。", {"購買一些營養軟泥淤泥，然後回到你興奮的軟泥怪朋友身邊。如果它看起來累了，可以試著跳舞來吸引它的注意力。"}},
[97617] = {"安全檢查", {"取回8個未經研究的文物、一頂探險者協會採礦盔帽和一把完好的鶴嘴鋤，然後交給洛克莫丹和荒蕪之地邊界的多嘉隆。"}},
[97663] = {"補給品與研究", {"殺死漫塵盆地附近的巨魔好搶回姆斯哈爾的遭竊補給品，然後再用它們來拓印附近的石頭雕紋，接著再回到卡加斯找姆斯哈爾。"}},
